/** Convert WGS84 longitude/latitude to the local metre grid. */
export function cerebralPosition(longitude: number, latitude: number): CerebralPosition {
  return {
    x: (longitude - CEREBRAL_ORIGIN.longitude) * 111320 * Math.cos(CEREBRAL_ORIGIN.latitude * Math.PI / 180),
    z: (latitude - CEREBRAL_ORIGIN.latitude) * 111320,
  };
}

/** Shared bilinear bare-earth surface. Samples outside the survey clamp to its edge. */
export function cerebralGroundHeight(x: number, z: number): number {
  const grid = CEREBRAL_GROUND_GRID;
  const u = Math.max(0, Math.min(grid.columns - 1, (x - grid.minX) / (grid.maxX - grid.minX) * (grid.columns - 1)));
  const v = Math.max(0, Math.min(grid.rows - 1, (grid.maxZ - z) / (grid.maxZ - grid.minZ) * (grid.rows - 1)));
  const x0 = Math.floor(u), z0 = Math.floor(v);
  const x1 = Math.min(x0 + 1, grid.columns - 1), z1 = Math.min(z0 + 1, grid.rows - 1);
  const tx = u - x0, tz = v - z0;
  const at = (column: number, row: number) => grid.values[row * grid.columns + column];
  return (at(x0, z0) * (1 - tx) + at(x1, z0) * tx) * (1 - tz)
    + (at(x0, z1) * (1 - tx) + at(x1, z1) * tx) * tz;
}

export const CEREBRAL_GROUND_SAMPLES: readonly CerebralGroundPoint[] = CEREBRAL_GROUND_GRID.values.map((y, index) => {
  const grid = CEREBRAL_GROUND_GRID;
  return {
    x: grid.minX + index % grid.columns / (grid.columns - 1) * (grid.maxX - grid.minX),
    z: grid.maxZ - Math.floor(index / grid.columns) / (grid.rows - 1) * (grid.maxZ - grid.minZ),
    y,
  };
});
